attribution_impact.py.source:
"""Read-only join: simulator object tables (objtables/<index>.json) x S1-02 episode provenance.

Per episode:
  * eligibility as the generator computes it (pickupable, parentReceptacles[0] not None, sweep-one px >= 196);
  * how many of those have parentReceptacles[0] == "Floor" although a real receptacle follows in the list
    (misattributed: they can never be a remove/move source and never count as a holder for controls);
  * how many eligible objects sit on a U container under the generator attribution vs under the
    first-non-Floor attribution (i.e. remove sources that exist / would exist);
  * U containers that hold eligible objects (control candidates inside U) under both attributions;
  * longest consecutive invisible run per sealed container, from the stored verdicts and from the
    private rendered pixels, to check the "a 20-frame window exists inside" statement.
"""
import json
import sys
from pathlib import Path

MIN_VISIBLE_PIXELS = 196
MIN_WINDOW = 20


def longest_zero_run(values):
    best = cur = 0
    for v in values:
        cur = cur + 1 if v == 0 else 0
        best = max(best, cur)
    return best


def main():
    roots = sys.argv[1].split(","); objdir = Path(sys.argv[2])
    out = []
    for root in roots:
        for d in sorted(Path(root).iterdir()):
            rp = d / "receipt.json"; wv = d / "provenance" / "window_verdicts.json"; r1 = d / "provenance" / "route_stage1.json"
            if not (rp.exists() and wv.exists() and r1.exists()):
                continue
            rec = json.loads(rp.read_text()); w = json.loads(wv.read_text()); plan = json.loads(r1.read_text())
            idx = int(rec["source_index"])
            tab = json.loads((objdir / f"{idx:05d}.json").read_text())
            if "error" in tab:
                out.append({"house": rec["house_id"], "error": tab["error"]}); continue
            objs = {o["objectId"]: o for o in tab["objects"]}
            lo, hi = w["window"]; s1lo, s1hi = plan["segments"]["sweep_one"]
            U = set(w["invisible"]); subjects = list(w["subjects"]); sealed = [c for c, s in w["subjects"].items() if s.get("sealed")]
            usable = set(subjects)
            # sweep-one pixels per object
            px1 = {}
            for i in range(s1lo, s1hi + 1):
                vis = json.loads((d / "private" / f"{i:04d}.frame.json").read_text())["object_visibility"]
                for oid, px in vis.items():
                    px1[oid] = max(px1.get(oid, 0), int(px))
            elig = []
            for oid, o in objs.items():
                if not o["pickupable"]:
                    continue
                parents = o.get("parentReceptacles") or []
                if not parents:
                    continue
                if px1.get(oid, 0) < MIN_VISIBLE_PIXELS:
                    continue
                first = parents[0]
                non_floor = [p for p in parents if p != "Floor"]
                elig.append({"oid": oid, "first": first, "alt": (non_floor[0] if non_floor else None), "parents": parents,
                             "misattributed": (first == "Floor" and bool(non_floor))})
            mis = [e for e in elig if e["misattributed"]]
            floor_only = [e for e in elig if e["parents"] == ["Floor"]]
            on_U_gen = [e for e in elig if e["first"] in U]
            on_U_alt = [e for e in elig if e["alt"] in U]
            # holders per container for controls
            hold_gen = {e["first"] for e in elig if e["first"] in usable}
            hold_alt = {e["alt"] for e in elig if e["alt"] in usable}
            # longest invisible runs inside the window, per sealed container
            frames = list(range(lo + 1, hi + 1))
            unocc = {c: [None] * len(frames) for c in sealed}
            pos = {f: k for k, f in enumerate(frames)}
            for row in w["verdicts"]:
                if row["container"] in unocc and row["observation_index"] in pos:
                    unocc[row["container"]][pos[row["observation_index"]]] = int(row["unoccluded"])
            rendered = {c: [] for c in subjects}
            for f in frames:
                vis = json.loads((d / "private" / f"{f:04d}.frame.json").read_text())["object_visibility"]
                for c in subjects:
                    rendered[c].append(int(vis.get(c, 0)))
            run_verdict = {c: longest_zero_run([v if v is not None else 1 for v in unocc[c]]) for c in sealed}
            run_render = {c: longest_zero_run(rendered[c]) for c in subjects}
            out.append({
                "house": rec["house_id"].rsplit("-", 1)[1], "status": rec["status"], "reason": rec.get("reason"), "U": len(U),
                "window_frames": hi - lo, "n_sealed": len(sealed), "n_usable": len(usable),
                "eligible": len(elig), "eligible_floor_first_misattributed": len(mis), "eligible_floor_only": len(floor_only),
                "misattributed_true_parents": sorted({e["alt"] for e in mis}),
                "eligible_on_U_generator": len(on_U_gen), "eligible_on_U_first_non_floor": len(on_U_alt),
                "on_U_gained": sorted((e["oid"], e["alt"]) for e in elig if e["alt"] in U and e["first"] not in U),
                "U_holders_generator": len(hold_gen & U), "U_holders_first_non_floor": len(hold_alt & U),
                "holders_generator": len(hold_gen), "holders_first_non_floor": len(hold_alt),
                "sealed_with_verdict_run_ge20": sum(1 for c in sealed if run_verdict[c] >= MIN_WINDOW and c not in U),
                "sealed_with_render_run_ge20": sum(1 for c in sealed if run_render[c] >= MIN_WINDOW and c not in U),
                "max_verdict_run_nonU": max([run_verdict[c] for c in sealed if c not in U] or [0]),
                "max_render_run_nonU": max([run_render[c] for c in subjects if c not in U] or [0]),
            })
    print(json.dumps(out))


if __name__ == "__main__":
    main()

