"""Read-only estimate for the window-design proposal (information only, not a new sample).

If the unobservable window were the LAST L frames of the transition instead of the whole transition,
how many of the 49 regenerated episodes would have U >= 1, and how many would have at least one
remove source on U (eligible object, sweep-one px >= 196, first-non-Floor parent in U)?  Also the
same for the FIRST L frames (window right after leaving the last viewpoint) and for the best L-frame
run anywhere (upper bound, would be selecting the window after the fact -- reported only as a bound).
Uses the stored per-frame verdicts (unoccluded sample counts) exactly as generation recorded them.
"""
import json
import sys
from pathlib import Path

MIN_VISIBLE_PIXELS = 196


def main():
    roots = sys.argv[1].split(","); objdir = Path(sys.argv[2])
    Ls = [20, 30, 40, 60]
    out = []
    for root in roots:
        for d in sorted(Path(root).iterdir()):
            rp = d / "receipt.json"; wv = d / "provenance" / "window_verdicts.json"; r1 = d / "provenance" / "route_stage1.json"
            if not (rp.exists() and wv.exists() and r1.exists()):
                continue
            rec = json.loads(rp.read_text()); w = json.loads(wv.read_text()); plan = json.loads(r1.read_text())
            idx = int(rec["source_index"]); tab = json.loads((objdir / f"{idx:05d}.json").read_text())
            objs = {o["objectId"]: o for o in tab["objects"]}
            lo, hi = w["window"]; s1lo, s1hi = plan["segments"]["sweep_one"]
            sealed = [c for c, s in w["subjects"].items() if s.get("sealed")]
            frames = list(range(lo + 1, hi + 1)); pos = {f: k for k, f in enumerate(frames)}
            unocc = {c: [1] * len(frames) for c in sealed}   # unknown -> treated as visible
            for row in w["verdicts"]:
                if row["container"] in unocc and row["observation_index"] in pos:
                    unocc[row["container"]][pos[row["observation_index"]]] = int(row["unoccluded"])
            px1 = {}
            for i in range(s1lo, s1hi + 1):
                vis = json.loads((d / "private" / f"{i:04d}.frame.json").read_text())["object_visibility"]
                for oid, px in vis.items():
                    px1[oid] = max(px1.get(oid, 0), int(px))
            holders = {}
            for oid, o in objs.items():
                if not o["pickupable"] or px1.get(oid, 0) < MIN_VISIBLE_PIXELS:
                    continue
                parent = next((p for p in (o.get("parentReceptacles") or []) if p != "Floor"), None)
                if parent is not None:
                    holders.setdefault(parent, []).append(oid)
            row = {"house": rec["house_id"].rsplit("-", 1)[1], "status": rec["status"], "null_window": rec.get("null_window"),
                   "U_whole": len(w["invisible"]), "window_frames": len(frames), "sources_whole": sum(len(holders.get(c, [])) for c in w["invisible"])}
            for L in Ls:
                if len(frames) < L:
                    row[f"L{L}"] = None; continue
                def u_of(seg):
                    return [c for c in sealed if all(v == 0 for v in unocc[c][seg[0]:seg[1]])]
                last = u_of((len(frames) - L, len(frames)))
                first = u_of((0, L))
                best, best_seg = [], None
                for s in range(0, len(frames) - L + 1):
                    u = u_of((s, s + L))
                    if len(u) > len(best):
                        best, best_seg = u, s
                row[f"L{L}"] = {"U_last": len(last), "sources_last": sum(len(holders.get(c, [])) for c in last),
                                "U_first": len(first), "sources_first": sum(len(holders.get(c, [])) for c in first),
                                "U_best_anywhere": len(best), "sources_best_anywhere": sum(len(holders.get(c, [])) for c in best), "best_start": best_seg}
            out.append(row)
    print(json.dumps(out))


if __name__ == "__main__":
    main()
